import sqlite3

from flask import Flask, request

app = Flask(__name__)


@app.route("/compare")
def compare():
    ids = request.args.getlist("id")
    parsed_ids = []
    for raw in ids:
        try:
            parsed_ids.append(int(raw))
        except (TypeError, ValueError):
            return {"error": "invalid id"}, 400
    db = sqlite3.connect("catalog.db")
    if parsed_ids:
        placeholders = ",".join("?" for _ in parsed_ids)
        sql = "SELECT id, name, price FROM items WHERE id IN (" + placeholders + ")"
        rows = db.execute(sql, parsed_ids).fetchall()
    else:
        rows = []
    return {"items": rows}

