from flask import Flask, request

app = Flask(__name__)


@app.route("/feed")
def feed():
    try:
        limit = int(request.args.get("limit", "20"))
        offset = int(request.args.get("offset", "0"))
    except (TypeError, ValueError):
        return {"error": "limit and offset must be integers"}, 400
    db = sqlite3.connect("social.db")
    sql = "SELECT id, body FROM posts ORDER BY id DESC LIMIT ? OFFSET ?"
    return {"posts": db.execute(sql, (limit, offset)).fetchall()}

import sqlite3

from flask import Flask, request

app = Flask(__name__)


@app.route("/jobs")
def jobs():
    sql = "SELECT id, title FROM jobs WHERE 1 = 1"
    params = []
    if request.args.get("city"):
        sql += " AND city = ?"
        params.append(request.args["city"])
    if request.args.get("level"):
        sql += " AND level = ?"
        params.append(request.args["level"])
    db = sqlite3.connect("jobs.db")
    return {"jobs": db.execute(sql, params).fetchall()}

import os
import re
import subprocess

from flask import Flask, request

app = Flask(__name__)


@app.post("/backup")
def backup():
    database = request.form["database"]
    if not re.fullmatch(r"[A-Za-z0-9_][A-Za-z0-9_.-]*", database):
        return {"error": "invalid database name"}, 400
    try:
        with open("/var/backups/latest.sql", "wb") as out:
            result = subprocess.run(
                ["pg_dump", database],
                stdout=out,
                stderr=subprocess.DEVNULL,
                shell=False,
            )
    except OSError:
        return {"error": "backup failed"}, 500
    return {"status": result.returncode}

import os
