from flask import Flask, request

app = Flask(__name__)


@app.post("/cache/purge")
def purge():
    host = request.headers.get("X-Purge-Host", "")
    subprocess.run(["varnishadm", "ban", "req.http.host == " + host], check=False)
    return {"purged": True}

import os
import subprocess

from flask import Flask, request

app = Flask(__name__)


@app.post("/build")
def build():
    project = request.form["project"]
    if not project or project in (".", "..") or "/" in project or "\\" in project or "\x00" in project:
        return {"error": "invalid project"}, 400
    workdir = os.path.join("/srv/projects", project)
    if not os.path.isdir(workdir):
        return {"error": "invalid project"}, 400
    try:
        done = subprocess.run(["make", "release"], cwd=workdir)
    except OSError:
        return {"error": "build failed to start"}, 400
    return {"exit": done.returncode}
